// === Настройки ===
const input = msg.payload;       // число из inject (7)
const names = ["Аня", "Борис", "Вика", "Глеб", "Даша"];

// === Проверка типа ===
let status;
if (typeof input !== "number") {
    status = "Ошибка: payload не число";
} else if (input < 0) {
    status = "Отрицательное";
} else {
    status = "Положительное";
}

// === Цикл for — сумма чисел от 1 до input ===
let sum = 0;
for (let i = 1; i <= input; i++) {
    sum += i;
}

// === Цикл for...of — перебор массива ===
const upperNames = [];
for (const name of names) {
    upperNames.push(name.toUpperCase());
}

// === Возвращаем объект с полем payload ===
msg.payload = {
    input: input,
    status: status,
    sum: sum,
    names: upperNames,
    count: upperNames.length
};

return msg;
